add_filter('woocommerce_package_rates', 'restrict_shipping_for_specific_product', 10, 2);

function restrict_shipping_for_specific_product($rates, $package) {
    $restricted_product_id = 13344; // Replace with your product ID
    $only_local_pickup = false;

    foreach ($package['contents'] as $item) {
        if ($item['product_id'] == $restricted_product_id) {
            $only_local_pickup = true;
            break;
        }
    }

    if ($only_local_pickup) {
        foreach ($rates as $rate_id => $rate) {
            // Keep only local pickup — this will hide ClickShip and all others
            if (strpos($rate->method_id, 'local_pickup') === false) {
                unset($rates[$rate_id]);
            }
        }
    }

    return $rates;
}

