add_action( 'wp_enqueue_scripts', function () {
	// Bail on anything WooCommerce-ish: shop, product, category, cart,
	// checkout, my-account. Only static pages get trimmed.
	if ( ! function_exists( 'is_woocommerce' ) ) {
		return;
	}
	if ( is_woocommerce() || is_cart() || is_checkout() || is_account_page() ) {
		return;
	}

	$drop = array(
		// Back In Stock Notifier — only meaningful on a single product page.
		// cwginstock_phone_js is intl-tel-input, one of the larger libraries here.
		'cwginstock_js', 'cwginstock_phone_js', 'cwginstock_popup',

		// Customer Reviews for WooCommerce — no reviews render outside products.
		'cr-frontend-js', 'cr-colcade',

		// WooCommerce Order Attribution — only needed where an order can start.
		'sourcebuster-js', 'wc-order-attribution',

		// Divi Machine AJAX archive filters — no filtered archive on static pages.
		'divi-ajax-filter-frontend-bundle', 'divi-filter-loadmore-js', 'divi-filter-masonry-js',
	);

	foreach ( $drop as $handle ) {
		wp_dequeue_script( $handle );
		wp_deregister_script( $handle );
	}
}, 99 );

