// Pass 1: normal dequeue, as late as possible.
add_action( 'wp_enqueue_scripts', function () use ( $sp_homepage_diet_handles ) {
	if ( ! is_front_page() ) {
		return;
	}
	foreach ( $sp_homepage_diet_handles as $handle ) {
		wp_dequeue_script( $handle );
		wp_deregister_script( $handle );
	}
	wp_dequeue_style( 'photoswipe-default-skin' );
}, PHP_INT_MAX );

// Pass 2: safety net at print time — even a script enqueued through a hook
// the dequeue misses cannot reach the page if its tag is emptied here.
// The homepage has no notify-me form or gallery zoom (verified), so these
// libraries have nothing to do there. Product pages are untouched.
add_filter( 'script_loader_tag', function ( $tag, $handle ) use ( $sp_homepage_diet_handles ) {
	if ( is_front_page() && in_array( $handle, $sp_homepage_diet_handles, true ) ) {
		return '';
	}
	return $tag;
}, 10, 2 );

// Stop WP stamping fetchpriority="high" on the first carousel product image —
// a below-the-fold thumbnail that competes with the real hero for bandwidth.
// (Our hero preload is a <link> tag, unaffected by this filter.)
add_filter( 'wp_get_loading_optimization_attributes', function ( $attrs ) {
	if ( is_front_page() && isset( $attrs['fetchpriority'] ) ) {
		unset( $attrs['fetchpriority'] );
	}
	return $attrs;
} );

